output_text:
[
  {
    "id": "must_pick_up_cart_at_entrance",
    "text": "A shopper is obliged to take the available cart at the entrance rather than merely interacting there in some unspecified way.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "pickup_cart_at_entrance": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_cart_at_entrance"
    }
  },
  {
    "id": "must_return_cart_to_corral",
    "text": "A shopper who uses a cart is obliged to return it to the top-left cart corral before leaving.",
    "abstraction": {
      "state_properties": {
        "cart_corral": "at(0,1)",
        "pushing_cart": "hasCart",
        "cart_parked_in_corral": "cartAt(0,1)"
      },
      "events": {
        "pickup_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_corral": {
          "pre": {
            "and": [
              "cart_corral",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_corral"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pickup_cart",
      "discharge": "return_cart_to_corral"
    }
  },
  {
    "id": "no_leaving_cart_outside_corral",
    "text": "It is forbidden to put the cart down anywhere except the designated cart corral at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_corral": "at(0,1)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "leave_cart_somewhere": {
          "pre": {
            "and": [
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart_somewhere",
          {
            "not": "cart_corral"
          }
        ]
      }
    }
  },
  {
    "id": "no_exit_with_unreturned_cart",
    "text": "It is forbidden to exit unless the shopper is no longer pushing the cart and the cart is parked in the corral.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_corral": "cartAt(0,1)",
        "pushing_cart": "hasCart",
        "cart_returned": {
          "and": [
            "cart_parked_in_corral",
            {
              "not": "pushing_cart"
            }
          ]
        }
      },
      "events": {
        "exit_store": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          {
            "not": "cart_returned"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying_items",
    "text": "It is forbidden to carry required groceries by hand; items should be picked up only while pushing the cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "holding_item_by_hand": "handFull"
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "pushing_cart"
              }
            ]
          },
          "post": null
        },
        "pickup_item_with_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "holding_item_by_hand",
          "pickup_item_without_cart"
        ]
      }
    }
  },
  {
    "id": "must_drop_cart_before_leaving_corral",
    "text": "When a shopper reaches the cart corral while still pushing the cart, they must not move away with it and should leave it there.",
    "abstraction": {
      "state_properties": {
        "cart_corral": "at(0,1)",
        "pushing_cart": "hasCart",
        "at_corral_with_cart": {
          "and": [
            "cart_corral",
            "pushing_cart"
          ]
        }
      },
      "events": {
        "move_away_from_corral_with_cart": {
          "pre": {
            "and": [
              "at_corral_with_cart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_away_from_corral_with_cart"
    }
  },
  {
    "id": "cart_phase_one_way_shelf_rule",
    "text": "While pushing a cart at certain shelf-service cells, eastward travel is forbidden, although the same location may be traversed differently after the cart has been returned.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "left_middle_service_cell": "at(1,3)",
        "far_right_lower_service_cell": "at(6,4)",
        "one_way_service_cell": {
          "or": [
            "left_middle_service_cell",
            "far_right_lower_service_cell"
          ]
        },
        "cart_phase_one_way_cell": {
          "and": [
            "pushing_cart",
            "one_way_service_cell"
          ]
        }
      },
      "events": {
        "east_from_cart_phase_one_way_cell": {
          "pre": {
            "and": [
              "cart_phase_one_way_cell",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "east_from_cart_phase_one_way_cell"
    }
  },
  {
    "id": "no_more_interactions_after_cart_return",
    "text": "After the cart has been returned to the corral, the shopper should proceed as a pedestrian and must not perform further store interactions.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_corral": "cartAt(0,1)",
        "not_pushing_cart": {
          "not": "hasCart"
        },
        "pedestrian_after_cart_return": {
          "and": [
            "cart_parked_in_corral",
            "not_pushing_cart"
          ]
        }
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "pedestrian_after_cart_return",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  }
]
